import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid id format");
            return;
        }

        // fields parameter allows selecting which columns to return
        // Default to safe columns if not specified
        String columns = "username, display_name, avatar_url";
        if (fields != null && !fields.isEmpty()) {
            // Allow callers to specify comma-separated field names
            // We filter out obviously dangerous keywords
            String normalized = fields.toLowerCase().trim();
            if (normalized.contains("drop") || normalized.contains("delete") ||
                normalized.contains("update") || normalized.contains("insert") ||
                normalized.contains("alter") || normalized.contains("--")) {
                resp.sendError(400, "Invalid fields parameter");
                return;
            }
            columns = fields;
        }

        String query = "SELECT " + columns + " FROM user_profiles WHERE user_id = " + userId;
        logger.info("Executing query for user " + userId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");

            ResultSetMetaData meta = rs.getMetaData();
            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnLabel(i) + "\":");
                    String val = rs.getString(i);
                    if (val == null) {
                        out.print("null");
                    } else {
                        out.print("\"" + val.replace("\"", "\\\"") + "\"");
                    }
                }
            }
            out.print("}");
            out.flush();

        } catch (SQLException e) {
            logger.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST updates profile - uses prepared statement (safe)
        String userId = req.getParameter("id");
        String displayName = req.getParameter("display_name");
        String avatarUrl = req.getParameter("avatar_url");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid id");
            return;
        }

        String sql = "UPDATE user_profiles SET display_name = ?, avatar_url = ? WHERE user_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, displayName);
            pstmt.setString(2, avatarUrl);
            pstmt.setInt(3, Integer.parseInt(userId));
            int rows = pstmt.executeUpdate();
            resp.setContentType("application/json");
            resp.getWriter().print("{\"updated\":" + rows + "}");
        } catch (SQLException e) {
            logger.warning("SQL error on update: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }
}
